"""Generate evidence reports without turning unmet requirements into passes."""
import argparse
import csv
import hashlib
import json
import os
from pathlib import Path
import subprocess
import xml.etree.ElementTree as ET
import zipfile
ROOT=Path(__file__).resolve().parents[2]

def main():
    p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);a=p.parse_args();out=a.run
    load=lambda n:json.loads((out/n).read_text());d=load('decision.json');s=load('summary.json');t=load('timing/summary.json');v=load('timing/full-verification.json');sm=load('kit-smoke/summary.json');status=load('pipeline-status.json');base=s['lqr']
    rows=list(csv.DictReader((out/'episodes.csv').open()));missed=[]
    for f in (out/'timing/on').glob('seed-*/*-ticks.csv'):
        for r in csv.DictReader(f.open()):
            if r['deadline_miss']=='True':missed.append(dict(trace=str(f.relative_to(out)),tick=int(r['tick']),release_lateness_ms=int(r['release_lateness_ns'])/1e6,processing_ms=int(r['control_ns'])/1e6,thread_cpu_ms=int(r['control_cpu_ns'])/1e6,sensing_lqr_ms=int(r['sensing_lqr_ns'])/1e6,feature_ms=int(r['feature_ns'])/1e6,budget_skipped=r['decision_skipped']=='True'))
    (out/'deadline-attribution.json').write_text(json.dumps(missed,indent=2)+'\n')
    gain={arm:100*(1-s[arm]['rmse_m']/s['student_comp']['rmse_m']) for arm in ('legacy_history','causal_history')}
    protocol=json.loads((ROOT/'tools/reviewer_v9/protocol.json').read_text())
    lines=['# LANS: matched causal-state training and single research pipeline','',
      '27 October 2026. Evidence report; empirical failures, blocked confirmation and unavailable physical validation are retained.','',
      '## What changed and why','',
      'Previous policies were trained before the distinct-proposal recovery and packet-expiry supervisor revision. The old input interface also omitted known response/recovery history. This creates policy/controller distribution mismatch. This finite study tests a separately versioned causal state representation under matched retraining; it does not assume that more training must produce an improvement.',
      'The causal_recovery_history_v9 interface retains 20 channels but explicitly versions three semantics: channel 14 is the known filtered-residual memory divided by 0.08; channel 15 is the EWMA of previously completed response ages divided by 0.04; channel 19 is the clipped age since the last distinct qualifying proposal divided by 0.05 (sentinel 1 if none). Channels 16 and 17 remain zero. The current request’s future inference/service/completion time is never available to the actor. Existing ABI guards refuse silent reinterpretation of old checkpoints. This is useful causal history, not proof of a fully Markov state.',
      'Two predeclared arms use the same compensated physical inputs, controller, fresh paired optimizer/critic, initialization, training seeds and six 100,000-step endpoints (600,000 new steps). Legacy-history masks channels 14/15/19; causal-history observes them. Both use submitted-request actor credit with fixed-step GAE and all-transition critic learning. Actor loss/entropy/KL and advantage normalization use valid request samples; this changes actor/critic scaling and is disclosed. No training extension or endpoint search follows the results. Historical teacher/student/PPO training budgets are additional.',
      'The initial policy logits are preserved by zeroing the new input columns. Old PPO and supervised-student controls also retain their logits and ignore the added history. Comparisons against the frozen student therefore include state/training adaptation effects and cannot establish pure reinforcement-learning value; the paired legacy-history arm is the corresponding feature ablation. Neither the student nor every historical baseline was retrained for this new state.',
      'The v8 supervisor, 50ms freshness cutoff, recovery, expiry-aware continuation, actuator constraints, objective, candidate weights and margin are unchanged. Model-based input forecasting uses only completed-response history, capped at 40ms, and keeps original observation timestamps. Stale authority is zero regardless of predicted benefit. This does not compensate for delayed LQR sensing or physical actuator/communication latency. Eight new interface contracts pass; previous immutable evidence remains independently sealed.','',
      '## Frozen fresh development comparison','',
      'The initial batched actor audit found one near-tie mismatch in student_comp: a batch selected +0.08 while the single-row execution selected 0.0. Float32 logits differed by roughly 1e-7; source, inputs and recorded decisions were unchanged. The original failed verification.log and batch-replay-discrepancy.json are preserved. The corrected independent audit evaluates EVERY neural decision with the actual one-observation execution shape, still requiring exact class agreement. This is an audit correction, not a tolerance relaxation or a rerun of unfavorable episodes. Random export/golden-vector agreement is finite evidence, not bitwise equivalence of all platforms or batch shapes.', '',
      f'The predeclared matrix contains {d["episodes"]} episodes: three actor/noise groups, 15/25m/s, two development paths, mirrored directions, nominal/tire/20ms/40ms/100ms cases and nine sources. All submitted actor outputs and causal query/history vectors, supervisor/filter/recovery decisions, physical states, actual actuator metrics and rewards were independently replayed: {d["transitions"]:,} transitions and {d["submitted_actor_decisions"]:,} neural decisions. There are {d["exact_100ms_lqr_pairs"]} exact 100ms/LQR trajectory matches. No reserved data were opened.',
      '', '| Controller | Tracking gain vs LQR | Heading change vs LQR | Steering-rate RMS change | Survival |','|---|---:|---:|---:|---:|']
    for source,m in s.items():lines.append(f'| {source} | {m["gain_vs_lqr_pct"]:+.3f}% | {100*(m["heading_rmse_rad"]/base["heading_rmse_rad"]-1):+.3f}% | {100*(m["rate_rms_rad_s"]/base["rate_rms_rad_s"]-1):+.3f}% | {m["survived"]}/{m["episodes"]} |')
    lines+=['',f'Student-relative tracking gains: legacy-history {gain["legacy_history"]:+.3f}%; causal-history {gain["causal_history"]:+.3f}%. Selected arm: **{d["selected"]}**. The unchanged criteria require at least 1% aggregate gain over LQR, both fixed corrections and the compensated student; positive student gain in every paired group; no survival loss; nominal tracking no more than 2% worse than LQR; heading and steering-rate RMS no more than 5% higher. Aggregate metrics do not imply every speed/path cell improves.','']
    for arm,screen in d['screens'].items():lines+=[f'**{arm}**: eligible={screen["eligible"]}; paired student gains: '+', '.join(f'{g:+.4f}%' for g in screen['paired_gains_vs_student_pct'])+'. '+('Failed checks: '+ '; '.join(screen['reasons'])+'.' if screen['reasons'] else 'All development selection checks passed.'),'']
    arm=d['selected'] or 'legacy_history';tm=t['profiles']['on']
    lines+=['## Original-deadline timing','',f'The corresponding selected actor is tested when one exists; otherwise the predeclared legacy-history arm is a platform diagnostic, not a research winner. This campaign uses {arm}, three actors, five actual worker cases and 5seconds per case, after untimed warmup. It retains original 10ms deadlines, pinned local/helper CPUs, lower helper priority and the predeclared 1ms optional-work guard. There is one recorded campaign and no retries to erase misses.',
      f'Controller result: **{tm["misses"]}/{tm["ticks"]} original deadlines missed**, functional checks={tm["functional_pass"]}, observed strict timing={tm["observed_timing_pass"]}. Full replay covers {v["controller_ticks"]} ticks and {v["query_vectors_verified"]} issued query vectors, including past timing/recovery state. {v["budget_decisions_skipped"]} admission decisions were skipped at the budget limit. Native C heartbeat: {sum(e["deadline_misses"] for e in t["heartbeat"])}/{sum(e["ticks"] for e in t["heartbeat"])} misses. Native heartbeat success does not validate controller timing or Webots.',
      'admission-analysis.json describes active authority, proposal classes and rejection reasons by method/delay without changing parameters. Near-zero admitted authority limits the size of any learned contribution; this descriptive finding does not prove that relaxing safety/freshness checks would be appropriate.',
      'deadline-attribution.json retains every miss, including release lateness, elapsed processing, thread CPU, sensing/LQR and feature work. The components may overlap and are not a proof of a unique root cause. Optional work cannot recover a deadline already lost to scheduling or mandatory processing. A finite zero-miss observation, if achieved, is not a hard real-time/WCET certificate. The fixed-step plant advances during software ticks; survival does not establish continuous-time physical safety during a host pause. Cross-version timing campaigns ran under different conditions and cannot prove a causal speedup.',
      '', '## Laptop package and external evidence','',f'The new Python3.10 ZIP contains all three frozen actors, explicit ABI/hash checks, Windows/macOS launchers, the full raw replay and no Torch dependency. The clean minimal-environment packaging smoke completed {sm["ticks"]} ticks, with {sm["deadline_misses"]} misses and fallback={sm["functional_fallback_pass"]}. Its half-second cases are packaging diagnostics, not strict qualification or actual laptop results.',
      'On the actual laptop, extract LANS_Causal_Python310_Kit.zip, then run RUN_WINDOWS.cmd or `bash RUN_MAC.command`. This performs five 13second cases per actor (195 measured seconds plus warmup), verifies the bundle before execution and produces laptop-results/Results.zip. Preserve failures. Import with the same pipeline command plus `--laptop-results /path/to/Results.zip`. The importer accepts data files only, validates the matching source/model bundle and independently replays 19,500 expected ticks. Participant data are not cryptographic hardware attestation.',
      '', '## One command and honest stage status','',
      'From the repository root using the Python3.10 research environment:', '', '```bash','python tools/controller_review/run_single_pipeline.py --publish','```','',
      'The command verifies old evidence; resumes the fixed six-training/1,080-episode protocol; executes timing once; replays raw data; builds and clean-tests the target kit; imports target data when supplied; seals evidence; creates editable Word/PDF reports; and optionally commits/pushes this branch. Completed stage outputs are retained. Partial runs are not silently overwritten. Exit 2 means at least one scientific/external requirement remains unmet, while exit 1 is an execution error. A successful file-generation stage never overrides an empirical failure.',
      '', '| Requirement | Current status |','|---|---|']
    for name,state in status['stages'].items():lines.append(f'| {name} | {state["state"]} |')
    lines+=['', 'Reserved/unseen-path evaluation and current-ABI native Webots confirmation remain gated on scientific selection plus corresponding-controller timing. If those gates pass later, confirmation still needs its declared protocol and current-controller integration; this orchestrator does not call the old student adapter and label it a new confirmation.',
      'A full robust vehicle safety-filter reproduction still requires justified vehicle uncertainty bounds, terminal safe set/backup, primary algorithm details and a matched evaluation. The existing verified scalar specialization is not that reproduction. Thirty-two references have structural checks and five uploaded primary versions are verified; the remaining primary-source/novelty audit is open. These research tasks cannot be passed by generating a stub.',
      'No physical sensor, communication or actuator evidence is available. Vehicle-readiness, global convergence, universal neuro-symbolic novelty, 49-fold speedup and measured energy superiority are excluded. A separately passing one-second worker recovery test from v8 does not cancel any current timing miss or prove improved tracking. Paper1 remains the residual LQR/PPO/supervisor architecture; V2V is excluded.',
      'These are reviewable evidence reports, not a submission-ready claim that unresolved requirements passed. Failures must motivate a justified new protocol or narrower claims, never relaxed thresholds or repeatedly reopening development outcomes until a score crosses a line.']
    (out/'README.md').write_text('\n'.join(lines)+'\n')
    completion=dict(selected=d['selected'],episodes=d['episodes'],transitions=d['transitions'],student_gain_pct=gain,training_steps=600000,strict_timing=tm,submission_ready=False,actual_laptop=(out/'target-laptop/import-verification.json').exists(),reserved_unopened=True,physical_validation=False)
    (out/'completion-status.json').write_text(json.dumps(completion,indent=2)+'\n')
    os.environ.setdefault('XDG_CACHE_HOME','/tmp/lans-v9-font-cache');Path(os.environ['XDG_CACHE_HOME']).mkdir(exist_ok=True)
    for suffix in ('docx','pdf'):
        cmd=['pandoc',str(out/'README.md'),'-o',str(out/f'pipeline-update.{suffix}')]
        if suffix=='pdf':cmd+=['--pdf-engine=xelatex','-V','mainfont=DejaVu Serif','-V','geometry:margin=22mm','-V','fontsize=10pt']
        subprocess.run(cmd,check=True)
    with zipfile.ZipFile(out/'pipeline-update.docx') as z:
        body=ET.fromstring(z.read('word/document.xml'));assert len(''.join(body.itertext()))>5000
    with zipfile.ZipFile(out/'LANS_Pipeline_Reports.zip','w',zipfile.ZIP_DEFLATED) as z:
        for name in ('README.md','pipeline-update.docx','pipeline-update.pdf','decision.json','summary.json','completion-status.json','pipeline-status.json','manifest.json','evidence-hashes.json','deadline-attribution.json','timing/protocol.json','timing/summary.json','timing/full-verification.json','tests.log','pipeline_contracts.log','batch-replay-discrepancy.json','admission-analysis.json','development-evidence-hashes.json'):z.write(out/name,name)
    checks={}
    for f in out.glob('*.zip'):
        with zipfile.ZipFile(f) as z:assert z.testzip() is None
        checks[f.name]=hashlib.sha256(f.read_bytes()).hexdigest()
    (out/'artifact-quality.json').write_text(json.dumps(dict(archive_crc_pass=True,word_xml_pass=True,sha256=checks),indent=2)+'\n');print(json.dumps(completion,indent=2))
if __name__=='__main__':main()
